const N = 24; // num of lines

// const { Point, Line, Polygon } = EpiShapeSvg;
const { EpiColors } = EpiColorsPckg;
let epiColors;


function setup() {
	createCanvas(S = max(windowWidth, windowHeight), S);
	noFill();
	noStroke();
	epiColors = new EpiColors();
	// epiColors.BG = EpiColors.getAdjustedBrightness(EpiColors.getAdjustedSaturation(epiColors.BG, 2), 0.35);
	loop();
}

function draw() {
	epiColors.getRandomPalette(true);
	background("#ffeeff"); // epiColors.BG
	fill(random(epiColors.palette));

	let mar, th, ww, hh;
	{
		mar = max(width, height) * 0.05;
		ww = width -mar -mar;
		hh = height -mar -mar;
		th = ~~(hh / N);
	}
	mar = (height - N*th)/2;
		ww = width -mar -mar;
		hh = height -mar -mar;

	let clrArrBlocked = [], clrArrEntropy = [];
	for (let i = 0; i < epiColors.palette.length; i++) clrArrEntropy.push(i);
	for (let i = 0, y = mar; i < N; i++, y += th) {
		// just allow 2 colors per line, palette.length must be >= 4
		shuffle(clrArrEntropy, true);
		let clrArrCurrLine = [];
		for (let j = 0; j < 2; j++) {
			clrArrCurrLine.push(clrArrEntropy[0]);
			clrArrEntropy.splice(0, 1);
		}
		const len = ~~(random(0.1, 0.9) * ww);
		fill(epiColors.palette[clrArrCurrLine[0]]);
		rect(mar, y, len, th);
		fill(epiColors.palette[clrArrCurrLine[1]]);
		rect(mar+len, y, ww-len, th);

		// freeing current blocked colors
		for (const clrIdx of clrArrBlocked) clrArrEntropy.push(clrIdx);
		// blocking new colors for next line
		clrArrBlocked = clrArrCurrLine;

		/*
		for (let x = mar; x < ww - mar;) {
			var len = min(ww-x-mar, ~~(random(0.1, 0.9) * ww));
			fill(random(epiColors.palette));
			rect(x, y, len, th);
			x += len;
		}
		*/
	}

	// noLoop() removed for animation
}

function mousePressed() {
	if (mouseButton != RIGHT && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > width*0.1) setup();
}
